struct bigNet *bigNetLoadAll(char *fileName) 
/* Load all bigNet from a whitespace-separated file.
 * Dispose of this with bigNetFreeList(). */
{
struct bigNet *list = NULL, *el;
struct lineFile *lf = lineFileOpen(fileName, TRUE);
char *row[26];

while (lineFileRow(lf, row))
    {
    el = bigNetLoad(row);
    slAddHead(&list, el);
    }
lineFileClose(&lf);
slReverse(&list);
return list;
}

struct bigNet *bigNetLoadAllByChar(char *fileName, char chopper) 
/* Load all bigNet from a chopper separated file.
 * Dispose of this with bigNetFreeList(). */
{
struct bigNet *list = NULL, *el;
struct lineFile *lf = lineFileOpen(fileName, TRUE);
char *row[26];

while (lineFileNextCharRow(lf, chopper, row, ArraySize(row)))
    {
    el = bigNetLoad(row);
    slAddHead(&list, el);
    }
lineFileClose(&lf);
slReverse(&list);
return list;
}

