int bigNetCmpTarget(const void *va, const void *vb)
/* Compare to sort based on target position, then by level. */
{
const struct bigNet *a = *((struct bigNet **)va);
const struct bigNet *b = *((struct bigNet **)vb);
int dif = strcmp(a->chrom, b->chrom);
if (dif == 0)
    dif = a->chromStart - b->chromStart;
if (dif == 0)
    dif = a->level - b->level;
return dif;
}
